def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize |k - OR(subarray)| over all nonempty contiguous subarrays."""
    best = max(k, max(nums))
    ending: set[int] = set()
    for value in nums:
        current = {value}
        current.update(previous | value for previous in ending)
        for result in current:
            best = min(best, abs(k - result))
            if best == 0:
                return 0
        ending = current
    return best"}
